-- Upgrade existing collections and seed the application detection catalog.
ALTER TABLE vm_applications ADD COLUMN IF NOT EXISTS confidence INTEGER DEFAULT 0;
ALTER TABLE vm_applications ALTER COLUMN confidence SET NOT NULL;
ALTER TABLE vm_applications ADD COLUMN IF NOT EXISTS app_vendor VARCHAR;
ALTER TABLE vm_applications ADD COLUMN IF NOT EXISTS app_category VARCHAR;

CREATE TABLE IF NOT EXISTS vm_vapp_products_tmp (
    vm_id VARCHAR PRIMARY KEY,
    products_json VARCHAR
);

CREATE TABLE IF NOT EXISTS vm_vapp_products (
    vm_id VARCHAR,
    key INTEGER NOT NULL DEFAULT 0,
    class_id VARCHAR,
    instance_id VARCHAR,
    name VARCHAR,
    vendor VARCHAR,
    version VARCHAR,
    full_version VARCHAR,
    vendor_url VARCHAR,
    product_url VARCHAR,
    app_url VARCHAR,
    UNIQUE (vm_id, key)
);

CREATE TABLE IF NOT EXISTS application_definitions (
    name VARCHAR PRIMARY KEY,
    description VARCHAR NOT NULL,
    vendor VARCHAR NOT NULL,
    category VARCHAR NOT NULL,
    certified VARCHAR NOT NULL CHECK (certified IN ('yes', 'no', 'maybe')),
    certification_comment VARCHAR NOT NULL,
    containerization_candidate BOOLEAN NOT NULL DEFAULT FALSE,
    match_mode VARCHAR NOT NULL DEFAULT '' CHECK (match_mode IN ('', 'any', 'all')),
    confidence INTEGER NOT NULL DEFAULT 0 CHECK (confidence BETWEEN 0 AND 100),
    process_names VARCHAR NOT NULL DEFAULT '[]',
    min_matched INTEGER NOT NULL DEFAULT 0,
    product_signatures VARCHAR NOT NULL DEFAULT '[]'
);

